mapper.insert:
INSERT INTO status_history
(student_no, status_no, reason, updated_at)
values (#{studentNo}, #{statusNo}, #{reason}, CURRENT_TIMESTAMP);

mapper.select:
SELECT s.student_id AS studentId, sth.TRANSFER_NO as historyNo, sth.MOVE_AT as moveAt, s.STUDENT_NAME as studentName, c.CLASS_NAME as className, u1.USERNAME as fromTeacher, u2.USERNAME as toTeacher, sth.TRANSFER_REASON as transferReason, sth.CREATED_AT as createdAt
FROM STUDENT_TRANSFER_HISTORY sth JOIN class_code c ON sth.class_no = c.class_no JOIN user_tb u1 ON sth.from_user_no = u1.user_no JOIN user_tb u2 ON sth.to_user_no = u2.user_no JOIN student_tb s ON sth.student_no = s.student_no JOIN grade_code g ON s.grade_no = g.grade_no
s.student_no = #{studentId}
